    penalty_calculate_no, ent_ceo_no, ent_emp_id, sell_products_no, period_start, period_end, penalty_fee_ratio, register_date, revision_date, use_status
) VALUES (
    #{penaltyCalculateNo}, #{entCeoNo}, #{entEmpId}, #{sellProductsNo}, #{periodStart}, #{periodEnd}, #{penaltyFeeRatio}, #{registerDate}, #{revisionDate}, #{useStatus}
)
